import{_ as t,a,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 19 The stuff of dreams","description":"学习 同位语从句与定语从句，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 19 The stuff of dreams","description":"学习 同位语从句与定语从句，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 同位语从句与定语从句，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 18 Porpoises","link":"/life/english/new-concept/book-4/unit-03/lesson-018"},"next":{"text":"第四册：流利英语 · Lesson 20 Snake poison","link":"/life/english/new-concept/book-4/unit-03/lesson-020"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 18 Porpoises","link":"/life/english/new-concept/book-4/unit-03/lesson-018"},"next":{"text":"第四册：流利英语 · Lesson 20 Snake poison","link":"/life/english/new-concept/book-4/unit-03/lesson-020"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-03/lesson-019.md","filePath":"life/english/new-concept/book-4/unit-03/lesson-019.md"}'),o={name:"life/english/new-concept/book-4/unit-03/lesson-019.md"};function s(l,e,r,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第四册-流利英语-·-lesson-19-the-stuff-of-dreams" tabindex="-1">第四册：流利英语 · Lesson 19 The stuff of dreams <a class="header-anchor" href="#第四册-流利英语-·-lesson-19-the-stuff-of-dreams" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 19 The stuff of dreams&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>借梦的主题练习区分个人回忆、心理解释和证据支持。梦境的生动程度不等于解释的可靠程度，历史观点也不自动代表当前共识。重点学习名词后同位语从句：准确表达某种想法的内容，同时说明这是想法、问题还是已经确认的事实。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>dream</td><td>/driːm/</td><td>n.</td><td>梦</td><td>recall a dream</td></tr><tr><td>memory</td><td>/ˈmeməri/</td><td>n.</td><td>记忆</td><td>a vivid memory</td></tr><tr><td>interpretation</td><td>/ɪnˌtɜːprəˈteɪʃən/</td><td>n.</td><td>解释</td><td>an alternative interpretation</td></tr><tr><td>hypothesis</td><td>/haɪˈpɒθəsɪs/</td><td>n.</td><td>假说</td><td>test a hypothesis</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>make sense of — 理解零散材料</li><li>be based on — 以某材料为依据</li></ul><h2 id="语法讲解-同位语从句与定语从句" tabindex="-1">语法讲解：同位语从句与定语从句 <a class="header-anchor" href="#语法讲解-同位语从句与定语从句" aria-label="Permalink to &quot;语法讲解：同位语从句与定语从句&quot;">​</a></h2><p>the idea that… 中 that 从句说明 idea 的内容，that 在从句中不充当主语或宾语；the idea that she proposed 中 that 代替 idea 作 proposed 的宾语，是定语从句。区分方法是看从句是否缺少成分。The claim that dreams predict events 的从句主谓宾完整，所以是内容从句。用 claim、belief 或 hypothesis 命名内容，能提醒读者这还不是已证实的事实。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The belief that every dream has one fixed meaning is difficult to justify.</p></blockquote><p>认为每个梦都有一个固定含义的信念很难得到充分支持。</p><p>that…meaning 说明 belief 的内容，内部主语 every dream、谓语 has、宾语 meaning 完整。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>不要把 belief 自动译成“事实”；the belief that 只标明某人持有的看法。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读长主语时不要在 that 前做句末停顿；在 belief 和 difficult to justify 上重读，体现评价层次。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I remembered a dream about a crowded station. It may have reflected my worries about an upcoming trip. That interpretation is possible, but it is not the only one.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句评价一个梦的解释：陈述回忆、提出可能联系、保留其他解释。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>回忆与解释分句处理，may 和 not the only one 避免把主观推测当成唯一答案。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例中的 that 从句说明 belief 的内容还是修饰提出它的人？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 说明 belief 的内容。</p><p><strong>解析：</strong> 从句本身结构完整。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>the story that she told 中 that 在从句作什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> told 的宾语。</p><p><strong>解析：</strong> she told 后缺少被讲述的对象。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将“关于梦会预示事件的主张”译成名词短语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the claim that dreams predict events</p><p><strong>解析：</strong> claim 后的完整内容从句表达主张本身。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：同位语从句与定语从句。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-018">上一课</a> · <a href="/life/english/new-concept/book-4/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-03/lesson-020">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=t(o,[["render",s]]);export{u as __pageData,f as default};
